import { Component, OnInit } from '@angular/core';
import { FormGroup, FormBuilder, Validators } from '@angular/forms';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { BankDetailModel } from 'src/app/data/model/common/BaseModel';
import { UserService } from 'src/app/data/service/user/user.service';

@Component({
  selector: 'app-bank-detail',
  templateUrl: './bank-detail.component.html',
  styleUrls: ['./bank-detail.component.scss']
})
export class BankDetailComponent implements OnInit {

  bankDetail: BankDetailModel;
  form: FormGroup;
  addMode = false;

  constructor(
    private userService: UserService,
    private fb: FormBuilder,
    public toastController: ToastController,
    public loadingController: LoadingController,
    public alertController: AlertController) { }

  ngOnInit(): void {

    this.form = this.fb.group({
      id: [0, [Validators.required, Validators.min(0)]],
      bankName: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(1000000)]],
      bankBranchName: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(1000000)]],
      bankBranchCode: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(1000000)]],
      cardCode: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(1000000)]],
      shebaCode: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(1000000)]],
      accountCode: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(1000000)]],
      accountType: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(1000000)]]
    });
  }

  ionViewWillEnter() {

    this.onGetData();
  }

  async presentAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onUpdate();
          }
        }
      ]
    });

    await alert.present();
  }

  onGetData() {

    SharedIonic.loading(this.loadingController);

    this.userService.GetSellerUserBankDetail().subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          this.bankDetail = res.data;

          this.form.setValue({
            id: res.data.id,
            bankName: res.data.bankName,
            bankBranchName: res.data.bankBranchName,
            bankBranchCode: res.data.bankBranchCode,
            cardCode: res.data.cardCode,
            shebaCode: res.data.shebaCode,
            accountCode: res.data.accountCode,
            accountType: res.data.accountType
          });
        } else {
          this.addMode = true;
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onUpdate() {

    if (this.form.valid) {

      SharedIonic.loading(this.loadingController);

      this.userService.AddOrUpdateSellerUserBankDetail(
        new BankDetailModel(
          this.addMode ? 0 : this.form.value.id,
          this.form.value.bankName,
          this.form.value.bankBranchName,
          this.form.value.bankBranchCode,
          this.form.value.cardCode,
          this.form.value.shebaCode,
          this.form.value.accountCode,
          this.form.value.accountType
        )
      ).subscribe(
        res2 => {
          if (res2.status === GResponse.SuccessStatus) {

            this.userService.GetSellerUserBankDetail().subscribe(
              res => {
                SharedIonic.dismissLoading(this.loadingController);
                if (res.status === GResponse.SuccessStatus) {
        
                  this.bankDetail = res.data;
                  this.addMode = false;
                  this.form.setValue({
                    id: res.data.id,
                    bankName: res.data.bankName,
                    bankBranchName: res.data.bankBranchName,
                    bankBranchCode: res.data.bankBranchCode,
                    cardCode: res.data.cardCode,
                    shebaCode: res.data.shebaCode,
                    accountCode: res.data.accountCode,
                    accountType: res.data.accountType
                  });
                } else {
                  this.addMode = true;
                }
              },
              err => {
                SharedIonic.dismissLoading(this.loadingController);
                SharedIonic.unSuccessToast(this.toastController);
              }
            );
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }
}
